      { t = "Lago Cristalino: mata múrlocs en la orilla este para [Amenaza viscosa] y recoge la chatarra brillante de su campamento ([Botellas y baratijas]). Entrégalas y acepta [Asunto de múrlocs]: llévasela a Remy \"Dos Veces\", en Villadorada, y acepta [Una oferta tentadora].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 53.9, y = 66.4, n = "Objetivo: Amenaza viscosa", q = 99128, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 56.2, y = 66.9, n = "Objetivo: Botellas y baratijas", q = 99143, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 47.5, y = 62.2, n = "Entregar: Amenaza viscosa (Jason Mathers)", q = 99128, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 47.6, y = 62.3, n = "Entregar: Botellas y baratijas (Lee Brown)", q = 99143, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 47.5, y = 62.2, n = "Recoger: Asunto de múrlocs (Jason Mathers)", q = 99129, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Entregar: Asunto de múrlocs (Remy \"Dos Veces\")", q = 99129, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Recoger: Una oferta tentadora (Remy \"Dos Veces\")", q = 99130, a = "A" } } },
      { t = "Baja al sur por el camino. En los viñedos de los Maclure, Maybell Maclure te da [Jóvenes enamorados]. En la granja de los Pedregosa, al oeste, \"Tía\" Bernice Pedregosa te da [El collar perdido] y La vieja Pedregosa, [¡Princesa debe morir!]: la cerda está en el este de Elwynn.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 89.6, n = "Recoger: Jóvenes enamorados (Maybell Maclure)", q = 106, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Recoger: El collar perdido (\"Tía\" Bernice Pedregosa)", q = 85, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 34.7, y = 84.5, n = "Recoger: ¡Princesa debe morir! (La vieja Pedregosa)", q = 88, a = "A" } } },
      { t = "Lleva la carta a Tommy Joe Pedregosa, al oeste de la granja ([Jóvenes enamorados]), y vuelve a la granja con [Habla con la abuelita]: Abuela Pedregosa te da [Una nota para William].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 29.8, y = 86.0, n = "Entregar: Jóvenes enamorados (Tommy Joe Pedregosa)", q = 106, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 29.8, y = 86.0, n = "Recoger: Habla con la abuelita (Tommy Joe Pedregosa)", q = 111, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 34.9, y = 83.9, n = "Entregar: Habla con la abuelita (Abuela Pedregosa)", q = 111, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 34.9, y = 83.9, n = "Recoger: Una nota para William (Abuela Pedregosa)", q = 107, a = "A" } } },
      { t = "Lleva el collar a Billy Maclure ([El collar perdido]) y acepta [Un pastel para Billy]. Mata jabalíes colmillopétreo alrededor de los viñedos para [Un pastel para Billy]: ellos y los osos jóvenes sueltan los viales de [Una oferta tentadora], y las flores que pide crecen al sur de la granja.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Entregar: El collar perdido (Billy Maclure)", q = 85, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Recoger: Un pastel para Billy (Billy Maclure)", q = 86, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 41.5, y = 87.3, n = "Objetivo: Un pastel para Billy", q = 86, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 38.7, y = 87.6, n = "Objetivo: Una oferta tentadora", q = 99130, a = "C" } } },
      { t = "Entrega [Un pastel para Billy] a \"Tía\" Bernice Pedregosa, en la granja, y acepta [Vuelve con Billy]. Lleva el pastel a Billy Maclure y acepta [Dientes de oro].", wp = { { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Entregar: Un pastel para Billy (\"Tía\" Bernice Pedregosa)", q = 86, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Recoger: Vuelve con Billy (\"Tía\" Bernice Pedregosa)", q = 84, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Entregar: Vuelve con Billy (Billy Maclure)", q = 84, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.1, y = 85.7, n = "Recoger: Dientes de oro (Billy Maclure)", q = 87, a = "A" } } },
      { t = "Mina Abisal, al norte de la granja: explórala ([La Mina Abisal]) y mata kóbolds para [Las velas de los kóbolds], [Intercambio de polvo de oro] y [Devolución de libros] (Nimsy, dentro, lleva el libro de los elementales). Dentdoro anda por la parte de arriba ([Dientes de oro]).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 39.7, y = 80.9, n = "Mina Abisal", q = 62, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.8, n = "Objetivo: Las velas de los kóbolds", q = 60, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.7, n = "Objetivo: Intercambio de polvo de oro", q = 47, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 39.8, y = 80.7, n = "Objetivo: Devolución de libros", q = 91775, a = "C" }, { m = 1429, z = "Bosque de Elwynn", x = 41.7, y = 78.0, n = "Objetivo: Dientes de oro", q = 87, a = "C" } } },
      { t = "Entrega [Dientes de oro] a \"Tía\" Bernice Pedregosa en la granja de los Pedregosa.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 34.5, y = 84.2, n = "Entregar: Dientes de oro (\"Tía\" Bernice Pedregosa)", q = 87, a = "T" } } },
      { t = "Vuelve a Villadorada: entrega [La Mina Abisal] y [Devolución de libros] a Alguacil Dughan (acepta [La Cantera de Jaspe]); [Las velas de los kóbolds] y [Una nota para William] a William Mortero (acepta [Un envío para Ventormenta] y [La recolección de Kelp]); [Intercambio de polvo de oro] y [Una oferta tentadora] a Remy \"Dos Veces\" (acepta [Cebo para el éxito] y [Un peligro con olor a pescado]). Lleva [Un peligro con olor a pescado] a Alguacil Dughan y acepta [Más preocupaciones], y [Cebo para el éxito] a Jason Mathers, en el lago.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: La Mina Abisal (Alguacil Dughan)", q = 62, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: Devolución de libros (Alguacil Dughan)", q = 91775, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Recoger: La Cantera de Jaspe (Alguacil Dughan)", q = 76, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Entregar: Las velas de los kóbolds (William Mortero)", q = 60, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Entregar: Una nota para William (William Mortero)", q = 107, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Recoger: Un envío para Ventormenta (William Mortero)", q = 61, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 43.3, y = 65.7, n = "Recoger: La recolección de Kelp (William Mortero)", q = 112, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Entregar: Intercambio de polvo de oro (Remy \"Dos Veces\")", q = 47, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Entregar: Una oferta tentadora (Remy \"Dos Veces\")", q = 99130, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Recoger: Cebo para el éxito (Remy \"Dos Veces\")", q = 99131, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 67.3, n = "Recoger: Un peligro con olor a pescado (Remy \"Dos Veces\")", q = 40, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Entregar: Un peligro con olor a pescado (Alguacil Dughan)", q = 40, a = "T" }, { m = 1429, z = "Bosque de Elwynn", x = 42.1, y = 65.9, n = "Recoger: Más preocupaciones (Alguacil Dughan)", q = 35, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 47.5, y = 62.2, n = "Entregar: Cebo para el éxito (Jason Mathers)", q = 99131, a = "T" } } },
      { t = "Nivel 8: entrena con Maximillian Crowe: Perdición de agonía (en Forever es una perdición, no una maldición: la llevas a la vez que una maldición) y Miedo (el enemigo huye unos segundos; un golpe fuerte lo rompe). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 44.4, y = 66.2, n = "Maximillian Crowe", npc = 906 } }, comprobar = { hechizos = { 980 } } },
      { t = "Misión extra para no quedarte corto de nivel: [Recompensas por los murlocs] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Recoger: Recompensas por los murlocs (Guardia Thomas)", q = 46, a = "A" }, { m = 1429, z = "Bosque de Elwynn", x = 74, y = 72.2, n = "Entregar: Recompensas por los murlocs (Guardia Thomas)", q = 46, a = "T" } } }, -- REFUERZO_97 q=46

      { t = "Misión extra en otra zona de tu nivel (Dun Morogh): [Operación Recombobulador] (nivel 10). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1426, z = "Dun Morogh", x = 45.9, y = 49.4, n = "Recoger: Operación Recombobulador (Razzle Energiodentado)", q = 412, a = "A" }, { m = 1426, z = "Dun Morogh", x = 26, y = 40.3, n = "Objetivo: Operación Recombobulador", q = 412, a = "C" }, { m = 1426, z = "Dun Morogh", x = 45.9, y = 49.4, n = "Entregar: Operación Recombobulador (Razzle Energiodentado)", q = 412, a = "T" } } }, -- REFUERZO_97 q=412
