  {
    titulo = "Ventormenta", min = 10, max = 11,
    entrenar = "Tu misión del 10 te da el abisario, tu demonio para toda la ruta: aguanta los golpes mientras tus daños en el tiempo trabajan. En Ventormenta tus instructores están en el sótano de El Cordero Degollado (Barrio de los Magos): Demisette Cloyce, Ursula Deline y Sandahl; en Forjaz, en el norte de la ciudad: Brezospina, Corazón de Cardo y Alexander Calder. Talentos: 10-14 Corrupción mejorada.",
    equipo = "En la subasta de Ventormenta, en el Distrito de Mercaderes, busca una varita: es tu mayor mejora. Si subes Encantamiento, con 10 puntos te haces la <Varita mágica inferior>.",
    profesion = "Sastrería 1-55: <Madeja de paño de lino> y <Cinturón de lino>. Encantamiento 1-20: Motas de magia (Mote of Magic). Primeros auxilios: <Venda de lino>.",
    pasos = {
      { t = "Sigue el camino al norte hasta Ventormenta. En el Distrito de Mercaderes activa el vuelo con Dungar Tragolargo y entrega [Un envío para Ventormenta] a Morgan Mortero.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 71.3, y = 72.2, n = "Dungar Tragolargo", npc = 352 }, { m = 1453, z = "Ciudad de Ventormenta", x = 63.2, y = 74.4, n = "Entregar: Un envío para Ventormenta (Morgan Mortero)", q = 61, a = "T" } } },
      { t = "Misión de clase: en el Barrio de los Magos, baja al sótano de El Cordero Degollado y entrega [La invocación de Gakin] a Gakin el Presotenebra. Te da [Surena Caledon]: búscala en el huerto de calabazas del sureste de Elwynn, donde mataste a Princesa.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Entregar: La invocación de Gakin (Gakin el Presotenebra)", q = 1685, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Recoger: Surena Caledon (Gakin el Presotenebra)", q = 1688, a = "A" } } },
      { t = "Nivel 10: si no entrenaste en Villadorada, hazlo con Demisette Cloyce, al lado: Drenar alma, Crear piedra de salud y los rangos 2 de Piel de demonio e Inmolar. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.0, n = "Demisette Cloyce", npc = 461 } }, comprobar = { hechizos = { 1120 } } },
      { t = "Profesiones en el Barrio de los Magos: Encantamiento con Betty Quin, en la tienda de encantamiento, y Sastrería con Lawrence Schneider si no la aprendiste en el campamento maderero. En la Plaza de la Catedral, Shaina Fuller enseña Primeros auxilios.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 73.7, n = "Betty Quin", npc = 11068 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.5, y = 81.5, n = "Lawrence Schneider", npc = 1300 }, { m = 1453, z = "Ciudad de Ventormenta", x = 53.0, y = 44.7, n = "Shaina Fuller", npc = 2327 } }, comprobar = { oficios = { 197, 333, 129 } } },
      { t = "Sal de Ventormenta y vuelve al huerto de calabazas del sureste de Elwynn: Surena Caledon está con Morgan el Coleccionista y Erlan Yermestia. Pon Miedo a uno, pelea con los otros de uno en uno y quítale la gargantilla ([Surena Caledon]).", wp = { { m = 1429, z = "Bosque de Elwynn", x = 71.0, y = 80.8, n = "Objetivo: Surena Caledon", q = 1688, a = "C" } } },
      { t = "Vuelve con Gakin el Presotenebra: entrega [Surena Caledon] y acepta [El vínculo]. Baja al círculo de invocación que hay debajo, usa la <Gargantilla de Petrosangre> y vence al abisario que sale. Entrega la misión: aprendes Invocar abisario. Invocarlo gasta un fragmento de alma: remata con Drenar alma para tener siempre alguno.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Entregar: Surena Caledon (Gakin el Presotenebra)", q = 1688, a = "T" }, { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Recoger: El vínculo (Gakin el Presotenebra)", q = 1689, a = "A" }, { m = 1453, z = "Ciudad de Ventormenta", x = 39.1, y = 84.4, n = "Objetivo: El vínculo", q = 1689, a = "C" }, { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Entregar: El vínculo (Gakin el Presotenebra)", q = 1689, a = "T" } } },
