  {
    titulo = "Loch Modan", min = 15, max = 18,
    entrenar = "Talentos: 10-14 Corrupción mejorada y 15-19 Supresión (fallas menos hechizos de Aflicción y das menos amenaza). Al 12: Cauce de salud (pasas vida a tu demonio) y Descarga de las Sombras (rango 3); al 14, Drenar vida (daño que te cura) y Corrupción (rango 2); al 16, Transfusión de vida (rango 2); al 18, Perdición de agonía (rango 2) y Crear piedra de alma. Vuela a Forjaz desde Thelsamar para entrenar.",
    equipo = "Busca piezas 'del búho' (Intelecto y Espíritu) en la subasta de Forjaz: a este nivel son baratas. En Forever Transfusión de vida da más maná cuanto más Espíritu tienes. Con encantamiento 70, la <Varita mágica superior> pega mucho más que la inferior. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "El paño de lana cae de troggs y ogros. A sastrería 50 aprende el rango oficial con Jormund Petrocejas y a encantamiento 50 con Gimble Cardopelusa: sin ellos no pasas de 75. Primeros auxilios: <Venda de lino pesado>.",
    pasos = {
      { t = "En el puesto de control del sur acepta [En defensa de las tierras del rey] y [La amenaza trogg]. Mata troggs Rompepiedras al este del puesto y entrégalas.", wp = { { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Recoger: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "A" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Recoger: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "A" }, { m = 1432, z = "Loch Modan", x = 32.4, y = 75.0, n = "Objetivo: En defensa de las tierras del rey", q = 224, a = "C" }, { m = 1432, z = "Loch Modan", x = 32.3, y = 75.3, n = "Objetivo: La amenaza trogg", q = 267, a = "C" }, { m = 1432, z = "Loch Modan", x = 22.1, y = 73.1, n = "Entregar: En defensa de las tierras del rey (Montaraz Pedernal)", q = 224, a = "T" }, { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Entregar: La amenaza trogg (Capitán Rugelfuss)", q = 267, a = "T" } } },
      { t = "Thelsamar: piedra de hogar en la posada, activa el vuelo con Thorgrum Borrelson y acepta [Mata ratas] y [Morcillas de Thelsamar].", wp = { { m = 1432, z = "Loch Modan", x = 35.5, y = 48.4, n = "Tabernero Hogartufa", npc = 6734 }, { m = 1432, z = "Loch Modan", x = 33.9, y = 51.0, n = "Thorgrum Borrelson", npc = 1572 }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Recoger: Mata ratas (Montaraz Kadrell)", q = 416, a = "A" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Recoger: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "A" } } },
      { t = "Haz [Morcillas de Thelsamar] (osos, jabalíes y arañas) y [Mata ratas] (ratas del túnel) al norte de Thelsamar.", wp = { { m = 1432, z = "Loch Modan", x = 34.8, y = 33.9, n = "Objetivo: Morcillas de Thelsamar", q = 418, a = "C" }, { m = 1432, z = "Loch Modan", x = 36.5, y = 22.6, n = "Objetivo: Mata ratas", q = 416, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.8, y = 49.3, n = "Entregar: Morcillas de Thelsamar (Vidra Hogartufa)", q = 418, a = "T" }, { m = 1432, z = "Loch Modan", x = 32.6, y = 49.7, n = "Entregar: Mata ratas (Montaraz Kadrell)", q = 416, a = "T" } } },
      { t = "Nivel 12-14: vuela de Thelsamar a Forjaz y entrena con Brezospina, en el norte de la ciudad: Cauce de salud, Descarga de las Sombras (rango 3), Maldición de debilidad (rango 2) y, al 14, Drenar vida y Corrupción (rango 2). Vuelve en grifo. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 50.4, y = 5.7, n = "Brezospina", npc = 5172 } }, comprobar = { hechizos = { 755 } } },
      { t = "Cabaña del Errante (este del lago): [La caza de crocoliscos], [La fanfarronada de un cazador] y [Suministros de Bingles] de Bingles Pimpampum.", wp = { { m = 1432, z = "Loch Modan", x = 81.8, y = 61.7, n = "Recoger: La caza de crocoliscos (Marek Coracero)", q = 385, a = "A" }, { m = 1432, z = "Loch Modan", x = 83.5, y = 65.5, n = "Recoger: La fanfarronada de un cazador (Daryl el Jovenzuelo)", q = 257, a = "A" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Recoger: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "A" } } },
