      { t = "Recoge las herramientas de Bingles en la orilla norte para [Suministros de Bingles].", wp = { { m = 1432, z = "Loch Modan", x = 51.5, y = 23.7, n = "Objetivo: Suministros de Bingles", q = 2038, a = "C" }, { m = 1432, z = "Loch Modan", x = 63.6, y = 47.9, n = "Entregar: Suministros de Bingles (Bingles Pimpampum)", q = 2038, a = "T" } } },
      { t = "Presa del norte: Ingeniero Jefe Hinderweir VII te da [Se aproxima una oscura amenaza]. Busca la pista junto a la rampa este de la presa, vuelve con él y acepta [Se aproxima una oscura amenaza]: se entrega en Los Humedales.", wp = { { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 250, a = "A" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Entregar: Se aproxima una oscura amenaza (Barril sospechoso)", q = 250, a = "T" }, { m = 1432, z = "Loch Modan", x = 56.0, y = 13.2, n = "Recoger: Se aproxima una oscura amenaza (Barril sospechoso)", q = 199, a = "A" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Entregar: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 199, a = "T" }, { m = 1432, z = "Loch Modan", x = 46.0, y = 13.6, n = "Recoger: Se aproxima una oscura amenaza (Ingeniero Jefe Hinderweir VII)", q = 161, a = "A" } } },
      { t = "Fortaleza Mo'grosh (nordeste): ogros élite para [Mercenarios] (Magistrado Romonariz, en Thelsamar): misión difícil, recomendable hacerla en grupo.", wp = { { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Recoger: Mercenarios (Magistrado Romonariz)", q = 255, a = "A" }, { m = 1432, z = "Loch Modan", x = 69.9, y = 24.2, n = "Objetivo: Mercenarios", q = 255, a = "C" }, { m = 1432, z = "Loch Modan", x = 34.6, y = 44.5, n = "Entregar: Mercenarios (Magistrado Romonariz)", q = 255, a = "T" } } },
      { t = "Opcional, al 17-18 y en grupo: en el puesto del sur, las dos últimas partes de [En defensa de las tierras del rey]; la última es contra el jefe trogg Grawmug y sus guardias.", wp = { { m = 1432, z = "Loch Modan", x = 23.2, y = 73.7, n = "Capitán Rugelfuss (puesto del sur)", npc = 1092 }, { m = 1432, z = "Loch Modan", x = 34.8, y = 90.5, n = "Gromug, jefe trogg", npc = 1205 } } },
