  {
    titulo = "Vuelta a Ventormenta", min = 20, max = 20,
    entrenar = "Nivel 20 = gran entrenamiento en Ventormenta con Demisette Cloyce, en El Cordero Degollado: Armadura demoníaca (sustituye a Piel de demonio), Maldición de los elementos (el enemigo recibe más daño de magia), Inmolar (rango 3), Descarga de las Sombras (rango 4) y Cauce de salud (rango 2). Talentos 20-24: Demonología > Poder profano (tu demonio pega más).",
    equipo = "Objetivo: completar la cadena [La hermandad de los Defias] hasta Las Minas de la Muerte. La última parte da <Bastón de Páramos de Poniente>, un buen bastón. En la mazmorra, Cocinitas suelta <Vara para remover galletas>: una de las mejores varitas de leveo. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Sastrería 55-100: <Madeja de paño de lana>, <Manteo de lana> y <Hombreras de lana con doble pespunte>. Primeros auxilios: <Venda de lana>.",
    pasos = {
      { t = "Nivel 20: vuela a Ventormenta y entrena con Demisette Cloyce en El Cordero Degollado (Barrio de los Magos): Armadura demoníaca, Maldición de los elementos, Inmolar (rango 3), Descarga de las Sombras (rango 4) y Cauce de salud (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.0, n = "Demisette Cloyce", npc = 461 } }, comprobar = { hechizos = { 706 } } },
      { t = "Opcional desde el 20: la súcubo o el íncubo, que pegan más que el abisario pero aguantan menos. Gakin el Presotenebra te da [Devoradora de almas]: te manda a Takar el Vidente, en Los Baldíos, que te pide el <Duramen> de Vallefresno ([Duramen]) para la súcubo o la <Figurilla de madera> ([¿Qué es el amor?]) para el íncubo; después vuelves con Gakin. El viaje a Kalimdor es largo: si no lo haces, el abisario te vale para toda la ruta.", wp = { { m = 1453, z = "Ciudad de Ventormenta", x = 39.2, y = 85.2, n = "Gakin el Presotenebra", npc = 6122 } } },
    },
  },
