  {
    titulo = "Marjal Revolcafango", min = 39, max = 42,
    entrenar = "Nivel 40: Maldición de los elementos (rango 3), Armadura demoníaca (rango 3), Inmolar (rango 5), Crear piedra de alma (rango 3), Aullido de terror (opcional) y doble especialización (10 de oro en tu instructor). Montura: Brezospina te da [Invoca un malignoecus] y Strahad Farsan, en Trinquete, te enseña el malignoecus gratis. Talentos: 41 Succionar vida (otro daño en el tiempo que te cura) y 42-46 Malevolencia.",
    equipo = "Busca en la subasta piezas con daño de Sombra, Intelecto, Espíritu y Aguante. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Theramore: Sastrería artesana con Timoteo Valión (200 y nivel 35) y [Atenciones médicas] de Primeros auxilios con Doctor Gustaf VanHowzen (225).",
    pasos = {
      { t = "Nivel 40: vuela de Costasur a Forjaz y entrena con Brezospina: Maldición de los elementos (rango 3), Armadura demoníaca (rango 3), Inmolar (rango 5) y Crear piedra de alma (rango 3). Acepta también [Invoca un malignoecus]: tu montura. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1455, z = "Forjaz", x = 50.4, y = 5.7, n = "Brezospina", npc = 5172 }, { m = 1455, z = "Forjaz", x = 50.4, y = 5.7, n = "Recoger: Invoca un malignoecus (Brezospina)", q = 4487, a = "A" } }, comprobar = { hechizos = { 11733 } } },
      { t = "Vuela a Menethil y coge el barco a Theramore. Compra 3 <Especias calmantes> a Helenia Olden, que las pedirá \"Ojolodo\" Jarl. Morgan Stern te da [Sopa de fangorroca con tropezones]: tortugas Fangorroca en la costa del Marjal. La segunda parte ([... con tropezones]) es del Pantano de las Penas: no la cojas.", wp = { { m = 1445, z = "Marjal Revolcafango", x = 66.4, y = 51.5, n = "Helenia Olden", npc = 4897 }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Recoger: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "A" }, { m = 1445, z = "Marjal Revolcafango", x = 59.5, y = 52.9, n = "Objetivo: Sopa de fangorroca con tropezones", q = 1204, a = "C" }, { m = 1445, z = "Marjal Revolcafango", x = 66.3, y = 45.5, n = "Entregar: Sopa de fangorroca con tropezones (Morgan Stern)", q = 1204, a = "T" } } },
